mapper.delete:
delete a from t_cruise_point_instance AS a,t_robot_inspection AS b
        where b.inspection_id = a.cruise_id
        AND b.robot_id = #{robotId, jdbcType=BIGINT}

mapper.select:
select
a.robot_id,
a.robot_code,
a.robot_name,
a.robot_status,
a.robot_type,
a.robot_ip,
a.robot_port,
a.light_ip,
a.light_port,
a.light_username,
a.light_password,
a.lnferad_IP,
a.Inferad_Port,
a.Inferad_username,
a.Inferad_password,
a.phote_path,
a.create_by,
a.create_date,
a.update_by,
a.update_date,
a.robot_factory,
a.is_use,
a.commission_date,
a.up_region_id,
a.robot_position,
a.remarks
from t_robot_info a
where 1 = 1
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.robot_code = #{robotCode, jdbcType=VARCHAR}
 and a.robot_name = #{robotName, jdbcType=VARCHAR}
 and a.robot_status = #{robotStatus, jdbcType=VARCHAR}
 and a.robot_type = #{robotType, jdbcType=INTEGER}
 and a.robot_ip = #{robotIp, jdbcType=VARCHAR}
 and a.robot_port = #{robotPort, jdbcType=INTEGER}
 and a.light_ip = #{lightIp, jdbcType=VARCHAR}
 and a.light_port = #{lightPort, jdbcType=VARCHAR}
 and a.light_username = #{lightUsername, jdbcType=VARCHAR}
 and a.light_password = #{lightPassword, jdbcType=VARCHAR}
 and a.lnferad_IP = #{lnferadIp, jdbcType=VARCHAR}
 and a.Inferad_Port = #{inferadPort, jdbcType=INTEGER}
 and a.Inferad_username = #{inferadUsername, jdbcType=VARCHAR}
 and a.Inferad_password = #{inferadPassword, jdbcType=VARCHAR}
 and a.phote_path = #{photePath, jdbcType=VARCHAR}
 and a.create_by = #{createBy, jdbcType=VARCHAR}
 and a.create_date = #{createDate, jdbcType=TIMESTAMP}
 and a.update_by = #{updateBy, jdbcType=VARCHAR}
 and a.update_date = #{updateDate, jdbcType=TIMESTAMP}
and a.robot_factory = #{robotFactory, jdbcType=VARCHAR},
and a.is_use = #{isUse, jdbcType=VARCHAR},
and a.commission_date = #{commissionDate, jdbcType=TIMESTAMP},
and a.up_region_id = #{upRegionId, jdbcType=BIGINT},
and a.robot_position = #{robotPosition, jdbcType=VARCHAR},
 and a.remarks = #{remarks, jdbcType=VARCHAR}

select
a.robot_id,
a.robot_code,
a.robot_name,
a.robot_status,
a.robot_type,
d.dict_note as robot_type_name,
a.robot_ip,
a.robot_port,
a.light_ip,
a.light_port,
a.light_username,
a.light_password,
a.lnferad_IP,
a.Inferad_Port,
a.Inferad_username,
a.Inferad_password,
a.phote_path,
a.create_by,
a.create_date,
a.update_by,
a.update_date,
b.dict_note as robot_factory_name,
a.robot_factory,
c.dict_note as is_use_name,
a.is_use,
a.commission_date,
f.region_name,
a.up_region_id,
e.dict_note as robot_position_name,
a.robot_position ,
a.remarks
from t_robot_info a
LEFT JOIN t_dict_business d ON a.robot_type=d.dict_code
LEFT JOIN t_dict_business b ON a.robot_factory=b.dict_code
LEFT JOIN t_dict_business c ON a.is_use=c.dict_code
LEFT JOIN t_dict_business e ON a.robot_position = e.dict_code
LEFT JOIN t_std_region f on a.up_region_id=f.region_id
where 1 = 1
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.robot_code = #{robotCode, jdbcType=VARCHAR}
 and a.robot_name like '%${robotName, jdbcType=VARCHAR}%'
 and a.robot_status = #{robotStatus, jdbcType=VARCHAR}
 and a.robot_type = #{robotType, jdbcType=INTEGER}
 and a.robot_ip = #{robotIp, jdbcType=VARCHAR}
 and a.robot_port = #{robotPort, jdbcType=INTEGER}
 and a.light_ip = #{lightIp, jdbcType=VARCHAR}
 and a.light_port = #{lightPort, jdbcType=VARCHAR}
 and a.light_username = #{lightUsername, jdbcType=VARCHAR}
 and a.light_password = #{lightPassword, jdbcType=VARCHAR}
 and a.lnferad_IP = #{lnferadIp, jdbcType=VARCHAR}
 and a.Inferad_Port = #{inferadPort, jdbcType=INTEGER}
 and a.Inferad_username = #{inferadUsername, jdbcType=VARCHAR}
 and a.Inferad_password = #{inferadPassword, jdbcType=VARCHAR}
 and a.phote_path = #{photePath, jdbcType=VARCHAR}
 and a.create_by = #{createBy, jdbcType=VARCHAR}
 and a.create_date = #{createDate, jdbcType=TIMESTAMP}
 and a.update_by = #{updateBy, jdbcType=VARCHAR}
 and a.update_date = #{updateDate, jdbcType=TIMESTAMP}
and a.robot_factory = #{robotFactory, jdbcType=VARCHAR}
and a.is_use = #{isUse, jdbcType=VARCHAR}
and a.commission_date = #{commissionDate, jdbcType=TIMESTAMP}
and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
and a.robot_position = #{robotPosition, jdbcType=VARCHAR}
 and a.remarks = #{remarks, jdbcType=VARCHAR}
